115→      if (batchDuplicates.length > 0) {
116→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
117→        return;
118→      }
119→
120→      // Check for filenames that match already-uploaded table names
121→      const existingNames = new Set(tables.map((tbl) => tbl.name));
122→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
123→      if (alreadyUploaded.length > 0) {
124→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
125→        return;
126→      }
127→
128→      let lastName = '';
129→      try {
130→        for (const file of files) {
131→          const formData = new FormData();
