  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→import { generateUUID } from '../utils/uuid';
 12→
 13→function generateId() {
 14→  return generateUUID();
 15→}
 16→
 17→export function AgentProvider({
 18→  children,
 19→  refreshTables,
 20→}: {
 21→  children: ReactNode;
 22→  refreshTables: () => Promise<void>;
 23→}) {
 24→  const userSessionId = useSessionId();
 25→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 26→  const [isStreaming, setIsStreaming] = useState(false);
 27→  const abortRef = useRef<AbortController | null>(null);
 28→  const textBufferRef = useRef('');
 29→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 30→  const assistantIdRef = useRef('');
 31→  const segmentsRef = useRef<ContentSegment[]>([]);
 32→  const currentTextRef = useRef('');
 33→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 34→  const sessionIdRef = useRef<string | null>(null);
 35→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 36→
 37→  const flushText = useCallback(() => {
 38→    const text = textBufferRef.current;
 39→    if (!text) return;
 40→    const id = assistantIdRef.current;
 41→    currentTextRef.current += text;
 42→    setMessages((prev) =>
 43→      prev.map((m) =>
 44→        m.id === id ? { ...m, content: m.content + text } : m
 45→      )
 46→    );
 47→    textBufferRef.current = '';
 48→  }, []);
 49→
 50→  const sendMessage = useCallback(
 51→    async (text: string, conversationId?: string | null) => {
 52→      if (isStreaming) return;
 53→
 54→      const userMsg: ChatMessage = {
 55→        id: generateId(),
 56→        role: 'user',
 57→        content: text,
 58→      };
 59→
 60→      const assistantId = generateId();
 61→      assistantIdRef.current = assistantId;
 62→      const assistantMsg: ChatMessage = {
 63→        id: assistantId,
 64→        role: 'assistant',
 65→        content: '',
 66→        toolCalls: [],
 67→        isStreaming: true,
 68→      };
 69→
 70→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 71→      setIsStreaming(true);
 72→      textBufferRef.current = '';
 73→      segmentsRef.current = [];
 74→      currentTextRef.current = '';
 75→      phaseRef.current = 'thinking';
 76→
 77→      // Build conversation history from current messages for resume fallback
 78→      const history = messages
 79→        .filter((m) => m.role === 'user' || m.role === 'assistant')
 80→        .map((m) => ({ role: m.role, content: m.content }));
 81→
 82→      // If there's pending history from a delete, start a new Langfuse session with that context
 83→      const pendingHistory = pendingHistoryRef.current;
 84→      pendingHistoryRef.current = null;
 85→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
 86→
 87→      const controller = new AbortController();
 88→      abortRef.current = controller;
 89→
 90→      // Extract all /skill-name references from message
 91→      let actualMessage = text;
 92→      let skills: string[] | undefined;
 93→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
 94→      if (slashMatches.length > 0) {
 95→        skills = slashMatches.map((m) => m[1]);
 96→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
 97→      }
 98→
 99→      await runAgentLoop(
100→        actualMessage,
101→        sessionIdRef.current,
102→        langfuseSessionId,
103→        pendingHistory ?? (history.length > 0 ? history : null),
104→        conversationId,
105→        {
106→          onTextChunk: (chunk) => {
107→            textBufferRef.current += chunk;
108→            if (!flushTimerRef.current) {
109→              flushTimerRef.current = setTimeout(() => {
110→                flushText();
111→                flushTimerRef.current = null;
112→              }, 50);
113→            }
114→          },
115→          onThinkingDone: () => {
116→            // Extended thinking just ended and a text block is starting.
117→            // Create a thinking segment from accumulated thinking text.
118→            if (flushTimerRef.current) {
119→              clearTimeout(flushTimerRef.current);
120→              flushTimerRef.current = null;
121→            }
122→            flushText();
123→            if (currentTextRef.current.trim()) {
124→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
125→              currentTextRef.current = '';
126→            }
127→            phaseRef.current = 'answer';
128→            setMessages((prev) =>
129→              prev.map((m) =>
130→                m.id === assistantId
131→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
132→                  : m
133→              )
134→            );
135→          },
136→          onToolCall: (pending: ToolCallResult) => {
137→            if (flushTimerRef.current) {
138→              clearTimeout(flushTimerRef.current);
139→              flushTimerRef.current = null;
140→            }
141→            flushText();
142→            if (currentTextRef.current.trim()) {
143→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
144→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
145→              currentTextRef.current = '';
146→            }
147→            // Add a pending tool segment so the input is shown immediately
148→            segmentsRef.current.push({
149→              type: 'tool',
150→              toolResult: pending,
151→            });
152→            setMessages((prev) =>
153→              prev.map((m) =>
154→                m.id === assistantId
155→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
156→                  : m
157→              )
158→            );
159→          },
160→          onToolResult: (result: ToolCallResult) => {
161→            // Merge result into pending tool segment (keep input info, add output)
162→            const pendingIdx = segmentsRef.current.findIndex(
163→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
164→            );
165→            if (pendingIdx !== -1) {
166→              const pending = segmentsRef.current[pendingIdx].toolResult!;
167→              segmentsRef.current[pendingIdx] = {
168→                type: 'tool',
169→                toolResult: {
170→                  ...pending,
171→                  ...result,
172→                  sql: result.sql || pending.sql,
173→                  toolName: result.toolName || pending.toolName,
174→                  command: result.command || pending.command,
175→                  toolInput: result.toolInput || pending.toolInput,
176→                },
177→              };
178→            } else {
179→              segmentsRef.current.push({ type: 'tool', toolResult: result });
180→            }
181→            setMessages((prev) =>
182→              prev.map((m) =>
183→                m.id === assistantId
184→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
185→                  : m
186→              )
187→            );
188→            refreshTables();
189→            // When a skill is created, notify SkillsPanel to refresh
190→            if (result.toolName?.includes('create_skill')) {
191→              window.dispatchEvent(new CustomEvent('skills-updated'));
192→            }
193→          },
194→          onSubagentStart: (data) => {
195→            if (flushTimerRef.current) {
196→              clearTimeout(flushTimerRef.current);
197→              flushTimerRef.current = null;
198→            }
199→            flushText();
200→            if (currentTextRef.current.trim()) {
201→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
202→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
203→              currentTextRef.current = '';
204→            }
205→            segmentsRef.current.push({
206→              type: 'subagent_start',
207→              subagentId: data.id,
208→              subagentName: data.name,
209→              text: data.prompt,
210→            });
211→            setMessages((prev) =>
212→              prev.map((m) =>
213→                m.id === assistantId
214→                  ? { ...m, segments: [...segmentsRef.current] }
215→                  : m
216→              )
217→            );
218→          },
219→          onSubagentEnd: (data) => {
220→            segmentsRef.current.push({
221→              type: 'subagent_end',
222→              subagentId: data.id,
223→              subagentName: data.name,
224→              chart_spec: data.chart_spec,
225→              sqlResults: data.sql_results,
226→              text: data.result,
227→            });
228→            setMessages((prev) =>
229→              prev.map((m) =>
230→                m.id === assistantId
231→                  ? { ...m, segments: [...segmentsRef.current] }
232→                  : m
233→              )
234→            );
235→          },
236→          onDone: (newSessionId) => {
237→            if (newSessionId) sessionIdRef.current = newSessionId;
238→            if (flushTimerRef.current) {
239→              clearTimeout(flushTimerRef.current);
240→              flushTimerRef.current = null;
241→            }
242→            flushText();
243→            if (currentTextRef.current.trim()) {
244→              segmentsRef.current.push({
245→                type: 'answer',
246→                text: currentTextRef.current,
247→              });
248→              currentTextRef.current = '';
249→            }
250→            setMessages((prev) =>
251→              prev.map((m) =>
252→                m.id === assistantId
253→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
254→                  : m
255→              )
256→            );
257→            setIsStreaming(false);
258→            abortRef.current = null;
259→          },
260→          onError: (error) => {
261→            if (flushTimerRef.current) {
262→              clearTimeout(flushTimerRef.current);
263→              flushTimerRef.current = null;
264→            }
265→            flushText();
266→            if (currentTextRef.current.trim()) {
267→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
268→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
269→              currentTextRef.current = '';
270→            }
271→            segmentsRef.current.push({ type: 'error', errorMessage: error });
272→            setMessages((prev) =>
273→              prev.map((m) =>
274→                m.id === assistantId
275→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
276→                  : m
277→              )
278→            );
279→            setIsStreaming(false);
280→            abortRef.current = null;
281→          },
282→          onUserQuestion: (data) => {
