284→                {language === 'en' ? 'EN' : '中'}
285→              </button>
286→              <button
287→                className="app__theme-toggle"
288→                onClick={toggleTheme}
289→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
290→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
