305→          <AgentPanel
306→            tables={tables}
307→            onUpload={handleFileUpload}
308→            onLoadSample={handleLoadSample}
309→            pendingSkillCommand={pendingSkillCommand}
310→            onSkillCommandConsumed={() => setPendingSkillCommand(null)}
311→          />
312→        </div>
313→      ) : (
314→        <div className="app__editor-wrapper">
315→          <div className="app__header">
316→            <h1 className="app__title">{t('appTitle')}</h1>
317→            <div className="app__header-actions">
318→              <button
319→                className="app__lang-toggle"
320→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
321→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
322→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
323→              >
324→                {language === 'en' ? 'EN' : '中'}
325→              </button>
326→              <button
327→                className="app__theme-toggle"
328→                onClick={toggleTheme}
329→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
330→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
331→              >
332→                {themeIcon}
333→              </button>
334→              <button
335→                className="app__agent-toggle"
336→                onClick={handleAgentToggle}
337→              >
338→                {t('agentMode')}
339→              </button>
340→            </div>
341→          </div>
342→          <div className="app__mode-header">
343→            <span className="app__mode-title">{t('editorMode')}</span>
344→          </div>
345→          {errorMessage && (
346→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
347→          )}
348→          <main className="app__main">
349→            {tables.length === 0 ? (
350→              <div className="app__empty">
351→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
352→              </div>
353→            ) : (
354→              <>
355→                <QueryEditor
356→                  onExecute={handleQueryExecute}
357→                  initialQuery={editorQuery}
358→                />
359→                {queryResult?.resultType === 'markdown' ? (
360→                  <ResultMarkdown result={queryResult} />
361→                ) : (
362→                  <ResultsTable result={queryResult} />
363→                )}
364→              </>
365→            )}
366→          </main>
367→        </div>
368→      )}
369→    </div>
370→  );
371→}
372→
373→export default function App() {
374→  const sessionId = useSessionId();
375→  const [tables, setTables] = useState<TableInfo[]>([]);
376→  const [loading, setLoading] = useState(true);
377→  const [error, setError] = useState<string | null>(null);
378→  const refreshTables = useCallback(async () => {
379→    try {
380→      const response = await fetch('/api/tables', {
381→        headers: { 'X-Session-ID': sessionId },
382→      });
383→      if (!response.ok) throw new Error('Failed to fetch tables');
384→      const data = await response.json();
385→      setTables(data);
386→    } catch (e) {
387→      console.error('Failed to refresh tables:', e);
388→    }
389→  }, [sessionId]);
390→
391→  useEffect(() => {
392→    (async () => {
393→      try {
394→        const response = await fetch('/api/health');
395→        if (!response.ok) throw new Error('Backend is not available');
396→        await refreshTables();
397→      } catch (e) {
398→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
399→      } finally {
400→        setLoading(false);
401→      }
402→    })();
403→  }, [refreshTables]);
404→
405→  if (loading) {
406→    return <div className="app-loading">Connecting to backend...</div>;
407→  }
408→
409→  if (error) {
410→    return (
411→      <div className="app-error">Failed to connect: {error}</div>
412→    );
413→  }
414→
415→  return (
416→    <ConfigProvider>
417→      <LanguageProvider>
418→        <ThemeProvider>
419→          <ConversationProvider>
420→            <AgentProvider refreshTables={refreshTables}>
421→              <AppContent tables={tables} refreshTables={refreshTables} sessionId={sessionId} />
422→            </AgentProvider>
423→          </ConversationProvider>
424→        </ThemeProvider>
425→      </LanguageProvider>
426→    </ConfigProvider>
427→  );
428→}
